import java.util.Scanner;

public class Main {
    public static long sumDigitsInBase(long k, long l) {
        long sum = 0;
        while (k != 0) {
            sum += k % l;
            k /= l;
        }
        return sum;
    }

    public static long gcd(long a, long b) {
        return (b == 0 ? a : gcd(b, a % b));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long f = 0;
        for (long i = 2; i < n; i++) {
            f += sumDigitsInBase(n, i);
        }
        long denominator = n - 2;
        long j = gcd(f, denominator);
        System.out.println((f / j) + "/" + (denominator / j));
        scanner.close();
    }
}

